WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_term_percent_point'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '百分数与百分点', 'kp-xingce-data-term-percent-point', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "百分数与百分点"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "率本身的绝对值叫“百分数”，率和率相减的差值叫“百分点”。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "常出现于“比重比上年提高了多少”、“增速比上年回落了多少”的选项判断和计算中。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "katexBlock", "attrs": {"content": "百分点 = 现期百分数 - 基期百分数"}}, {"type": "paragraph", "content": [{"type": "text", "text": "注意：百分点是一个带单位的绝对值（单位就是'个百分点'），绝对不能写成带 % 的相对值。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[题目问: 比重/增速提高了多少?] --> B[定位现期比重和基期比重]\nB --> C[做减法: A% - B%]\nC --> D[得出结果数值 X]\nD --> E[去选项找: X 个百分点, 坚决排掉带 % 的选项]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2023年某省第三产业比重为 45.2%，2022年为 43.1%。问：2023年第三产业比重比上年？"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A. 提高了 2.1%    B. 提高了 2.1 个百分点"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "识别：考查比重变化量的单位表达。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "计算：45.2% - 43.1% = 2.1。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "定单位：两个百分数直接相减，结果单位必须是“个百分点”。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "秒选 B。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "⚠️ 材料的不规范表达陷阱：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "有些不严谨的材料原文会写“增速提高了 5%”，这实际上等同于提高了 5个百分点。但你在选答案时，只要选项里有“百分点”，必须选它，不能选带 % 的干扰项！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "在做“比重差”、“平均数增长率”的题目时，强迫自己在计算出结果前先扫一眼选项的单位，把带错单位的卧底选项直接划掉。"}]}]}$$ AS jsonb), NULL, '百分数与百分点的核心考点与速算。', category_node.id, CAST('["资料分析", "百分数与百分点"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_term_percent_point", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
